local PouringCrucibleDrierMaker = {}
local PRODUCTS = {
    iron_pouringcrucibledrier = { name = "Železni sušilec za lončne peči", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sušilec za lončne peči za livarje." },
    bronze_pouringcrucibledrier = { name = "Bronast sušilec za lončne peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sušilec za lončne peči za livarje." },
    silver_pouringcrucibledrier = { name = "Srebrn sušilec za lončne peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sušilec za lončne peči za livarje." },
    gilded_pouringcrucibledrier = { name = "Pozlačen sušilec za lončne peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sušilec za lončne peči za livarje." },
    jewel_set_pouringcrucibledrier = { name = "Draguljast sušilec za lončne peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sušilec za lončne peči za livarje." },
    royal_sovereign_pouringcrucibledrier = { name = "Kraljevski suveren sušilec za lončne peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sušilec za lončne peči z biseri za krono." },
}
local BUILDINGS = {
    pouringcrucibledrier_workshop = { name = "Pouringcrucibledrier delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    pouringcrucibledrier_house = { name = "Pouringcrucibledrier hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_pouringcrucibledrier_atelier = { name = "Mojstrski pouringcrucibledrier atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_pouringcrucibledrier_palace = { name = "Suverena pouringcrucibledrier palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PouringCrucibleDrierMaker.ironStock=14; PouringCrucibleDrierMaker.bronzeStock=12; PouringCrucibleDrierMaker.woodStock=12; PouringCrucibleDrierMaker.leatherStock=8; PouringCrucibleDrierMaker.silverStock=8; PouringCrucibleDrierMaker.goldStock=6; PouringCrucibleDrierMaker.jewelStock=4; PouringCrucibleDrierMaker.pearlStock=4
PouringCrucibleDrierMaker.productStock = {}; PouringCrucibleDrierMaker.buildings = {}; PouringCrucibleDrierMaker.maker = nil; PouringCrucibleDrierMaker.activeMaking = {}; PouringCrucibleDrierMaker.totalProducts = 0; PouringCrucibleDrierMaker.dayTimer = 0
function PouringCrucibleDrierMaker.init() PouringCrucibleDrierMaker.ironStock=14; PouringCrucibleDrierMaker.bronzeStock=12; PouringCrucibleDrierMaker.woodStock=12; PouringCrucibleDrierMaker.leatherStock=8; PouringCrucibleDrierMaker.silverStock=8; PouringCrucibleDrierMaker.goldStock=6; PouringCrucibleDrierMaker.jewelStock=4; PouringCrucibleDrierMaker.pearlStock=4; PouringCrucibleDrierMaker.productStock={}; PouringCrucibleDrierMaker.buildings={}; PouringCrucibleDrierMaker.maker=nil; PouringCrucibleDrierMaker.activeMaking={}; PouringCrucibleDrierMaker.totalProducts=0; PouringCrucibleDrierMaker.dayTimer=0; print("[PouringCrucibleDrierMaker] Royal Pouring Crucible Drier Maker System initialized (6 products, 4 buildings)") end
function PouringCrucibleDrierMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PouringCrucibleDrierMaker.maker={name=n or ("Sušilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sušilnik najet: %s (spretnost: %d)",PouringCrucibleDrierMaker.maker.name,s),"success") end; return true end
function PouringCrucibleDrierMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PouringCrucibleDrierMaker.build(id) local ok,e=PouringCrucibleDrierMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PouringCrucibleDrierMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PouringCrucibleDrierMaker.getQualityBonus() local b=0; for _,bd in ipairs(PouringCrucibleDrierMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PouringCrucibleDrierMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PouringCrucibleDrierMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PouringCrucibleDrierMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PouringCrucibleDrierMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PouringCrucibleDrierMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PouringCrucibleDrierMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PouringCrucibleDrierMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PouringCrucibleDrierMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PouringCrucibleDrierMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PouringCrucibleDrierMaker.buildings==0 then return false,"Potrebna sušilna delavnica" end; if not PouringCrucibleDrierMaker.maker then return false,"Potreben susilnik" end; return true end
function PouringCrucibleDrierMaker.make(pt,qty) qty=qty or 1; local ok,e=PouringCrucibleDrierMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PouringCrucibleDrierMaker.ironStock=PouringCrucibleDrierMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PouringCrucibleDrierMaker.bronzeStock=PouringCrucibleDrierMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PouringCrucibleDrierMaker.woodStock=PouringCrucibleDrierMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PouringCrucibleDrierMaker.leatherStock=PouringCrucibleDrierMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PouringCrucibleDrierMaker.silverStock=PouringCrucibleDrierMaker.silverStock-d.silverCost*qty end; if d.goldCost then PouringCrucibleDrierMaker.goldStock=PouringCrucibleDrierMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PouringCrucibleDrierMaker.jewelStock=PouringCrucibleDrierMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PouringCrucibleDrierMaker.pearlStock=PouringCrucibleDrierMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PouringCrucibleDrierMaker.maker then t=math.max(1,t-math.floor(PouringCrucibleDrierMaker.maker.skill/13)) end; table.insert(PouringCrucibleDrierMaker.activeMaking,{id="pouringcrucibledrier_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PouringCrucibleDrierMaker.completeMaking(m) local q=1.0+(PouringCrucibleDrierMaker.getQualityBonus()/100); if PouringCrucibleDrierMaker.maker then q=q+(PouringCrucibleDrierMaker.maker.skill/140) end; q=math.min(2.5,q); PouringCrucibleDrierMaker.productStock[m.productType]=(PouringCrucibleDrierMaker.productStock[m.productType] or 0)+m.quantity; PouringCrucibleDrierMaker.totalProducts=PouringCrucibleDrierMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PouringCrucibleDrierMaker.maker then PouringCrucibleDrierMaker.maker.itemsMade=PouringCrucibleDrierMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PouringCrucibleDrierMaker.maker.skill=math.min(100,PouringCrucibleDrierMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sušilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pouringcrucibledrier.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PouringCrucibleDrierMaker.update(dt) if not _G.state then return end; PouringCrucibleDrierMaker.dayTimer=PouringCrucibleDrierMaker.dayTimer+dt; if PouringCrucibleDrierMaker.dayTimer>=30 then PouringCrucibleDrierMaker.dayTimer=0; for i=#PouringCrucibleDrierMaker.activeMaking,1,-1 do local m=PouringCrucibleDrierMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PouringCrucibleDrierMaker.completeMaking(m); table.remove(PouringCrucibleDrierMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PouringCrucibleDrierMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PouringCrucibleDrierMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PouringCrucibleDrierMaker.getStats() return {ironStock=PouringCrucibleDrierMaker.ironStock,bronzeStock=PouringCrucibleDrierMaker.bronzeStock,woodStock=PouringCrucibleDrierMaker.woodStock,leatherStock=PouringCrucibleDrierMaker.leatherStock,silverStock=PouringCrucibleDrierMaker.silverStock,goldStock=PouringCrucibleDrierMaker.goldStock,jewelStock=PouringCrucibleDrierMaker.jewelStock,pearlStock=PouringCrucibleDrierMaker.pearlStock,productStock=PouringCrucibleDrierMaker.productStock,numBuildings=#PouringCrucibleDrierMaker.buildings,hasMaker=PouringCrucibleDrierMaker.maker~=nil,makerName=PouringCrucibleDrierMaker.maker and PouringCrucibleDrierMaker.maker.name or "—",makerSkill=PouringCrucibleDrierMaker.maker and PouringCrucibleDrierMaker.maker.skill or 0,activeMaking=#PouringCrucibleDrierMaker.activeMaking,totalProducts=PouringCrucibleDrierMaker.totalProducts} end
return PouringCrucibleDrierMaker
